<script setup lang="ts">
import {ref,computed,onMounted} from 'vue';
type Project={id:number;name:string};type Item={text:string;done:boolean};type Task={id:number;title:string;description:string|null;project_id:number|null;status:string;priority:string;due_date:string|null;checklist:Item[]|null};
const user=ref<{name:string;email:string}|null>(null),projects=ref<Project[]>([]),tasks=ref<Task[]>([]),ready=ref(false),busy=ref(false),error=ref(''),csrf=ref('');
const register=ref(false),name=ref(''),email=ref(''),password=ref(''),confirmation=ref(''),view=ref('today'),query=ref(''),board=ref(false),project=ref<number|null>(null),draft=ref<Task|null>(null),newTitle=ref(''),newProject=ref<number|null>(null),newDate=ref(''),showAdd=ref(false),showProjects=ref(false),projectName=ref(''),subtext=ref(''),light=ref(false);
function today(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
const dateText=new Date().toLocaleDateString('ru-RU',{weekday:'long',day:'numeric',month:'long'});
async function api(path:string,method='GET',body?:unknown){const r=await fetch(path,{method,headers:{Accept:'application/json','Content-Type':'application/json','X-CSRF-TOKEN':csrf.value},credentials:'same-origin',...(body===undefined?{}:{body:JSON.stringify(body)})});if(r.status===204)return null;const d=await r.json();if(!r.ok){if(r.status===401){user.value=null;tasks.value=[];projects.value=[]}throw Error(d.errors?Object.values(d.errors).flat().join(' '):r.status===419?'Сессия истекла. Обновите страницу.':d.message||'Не удалось выполнить запрос.')}return d}
async function run(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';try{await fn()}catch(e){error.value=e instanceof Error?e.message:'Ошибка соединения. Попробуйте ещё раз.'}finally{busy.value=false}}
async function load(){const d=await api('/data');projects.value=d.projects;tasks.value=d.tasks}
onMounted(async()=>{try{const s=await api('/session');csrf.value=s.csrf;user.value=s.user;if(user.value)await load()}catch{error.value='Не удалось подключиться к серверу.'}finally{ready.value=true}});
function auth(){run(async()=>{const d=await api(register.value?'/register':'/login','POST',{name:name.value,email:email.value.trim().toLowerCase(),password:password.value,password_confirmation:confirmation.value});user.value=d.user;csrf.value=d.csrf;password.value='';confirmation.value='';await load()})}
function logout(){run(async()=>{const s=await api('/logout','POST');csrf.value=s.csrf;user.value=null;tasks.value=[];projects.value=[];draft.value=null})}
const heading=computed(()=>view.value==='project'?projects.value.find(p=>p.id===project.value)?.name:({today:'Сегодня',inbox:'Входящие',upcoming:'Предстоящие',all:'Все задачи'} as Record<string,string>)[view.value]);
const visible=computed(()=>tasks.value.filter(t=>(view.value==='project'?t.project_id===project.value:view.value==='today'?t.due_date===today():view.value==='inbox'?!t.project_id:view.value==='upcoming'?(t.due_date||'')>today():true)&&(!query.value||(t.title+' '+(t.description||'')).toLowerCase().includes(query.value.toLowerCase()))));
function select(t:Task){draft.value=JSON.parse(JSON.stringify({...t,checklist:t.checklist||[]}));subtext.value=''}
function navigate(v:string,p:number|null=null){view.value=v;project.value=p;draft.value=null;showProjects.value=false}
function addTask(){run(async()=>{const t=await api('/tasks','POST',{title:newTitle.value.trim(),project_id:newProject.value,due_date:newDate.value||null});tasks.value.push(t);showAdd.value=false;newTitle.value='';select(t)})}
function createProject(){run(async()=>{const p=await api('/projects','POST',{name:projectName.value.trim()});projects.value.push(p);projectName.value='';navigate('project',p.id)})}
function saveTask(){run(async()=>{if(!draft.value)return;const t=await api('/tasks/'+draft.value.id,'PATCH',draft.value);tasks.value=tasks.value.map(x=>x.id===t.id?t:x);select(t)})}
function toggle(t:Task){run(async()=>{const u=await api('/tasks/'+t.id,'PATCH',{status:t.status==='done'?'todo':'done'});tasks.value=tasks.value.map(x=>x.id===u.id?u:x);if(draft.value?.id===u.id)select(u)})}
function remove(){if(!draft.value||!confirm('Удалить задачу?'))return;run(async()=>{const id=draft.value!.id;await api('/tasks/'+id,'DELETE');tasks.value=tasks.value.filter(t=>t.id!==id);draft.value=null})}
function addSub(){if(subtext.value.trim()&&draft.value){draft.value.checklist!.push({text:subtext.value.trim(),done:false});subtext.value=''}}
const columns=[{id:'todo',name:'К выполнению'},{id:'doing',name:'В работе'},{id:'done',name:'Готово'}];const pname=(id:number|null)=>projects.value.find(p=>p.id===id)?.name||'';
</script>
<template>
<div :class="['shell',{light}]">
 <div v-if="!ready" class="loading">◇ СовДело · Загрузка…</div>
 <main v-else-if="!user" class="auth"><div class="auth-brand">◇ <b>СовДело</b></div><p class="muted">Всё по делу. Вместе.</p><form @submit.prevent="auth"><h1>{{register?'Создать аккаунт':'С возвращением'}}</h1><p class="muted">Ваши проекты и задачи в одном месте</p><label v-if="register">Имя<input v-model="name" required maxlength="120" autocomplete="name"></label><label>Email<input v-model="email" type="email" required autocomplete="username"></label><label>Пароль<input v-model="password" type="password" required :minlength="register?10:undefined" maxlength="128" :autocomplete="register?'new-password':'current-password'"></label><label v-if="register">Повторите пароль<input v-model="confirmation" type="password" required autocomplete="new-password"></label><p v-if="error" class="error" role="alert">{{error}}</p><button class="primary wide" :disabled="busy">{{busy?'Подождите…':register?'Зарегистрироваться':'Войти'}}</button><button type="button" class="link wide" @click="register=!register;error=''">{{register?'Уже есть аккаунт? Войти':'Нет аккаунта? Зарегистрироваться'}}</button></form><small class="muted">СовДело 0.1 · Локальный Laravel</small></main>
 <template v-else>
 <aside class="sidebar"><div class="brand">◇ <b>СовДело</b></div><nav><button v-for="n in [{v:'inbox',t:'Входящие',i:'▱'},{v:'today',t:'Сегодня',i:'▣'},{v:'upcoming',t:'Предстоящие',i:'◷'},{v:'all',t:'Все задачи',i:'☷'}]" :key="n.v" :class="{active:view===n.v}" @click="navigate(n.v)"><span>{{n.i}}</span>{{n.t}}</button></nav><p class="eyebrow">ПРОЕКТЫ</p><nav><button v-for="p in projects" :key="p.id" :class="{active:view==='project'&&project===p.id}" @click="navigate('project',p.id)">◇ {{p.name}}</button></nav><form class="project-create" @submit.prevent="createProject"><input v-model="projectName" placeholder="Новый проект…" required maxlength="120" aria-label="Название проекта"><button :disabled="busy" aria-label="Создать проект">＋</button></form><div class="sidebar-bottom"><span class="muted">{{user.name}}</span><small>{{user.email}}</small><button class="link" @click="logout" :disabled="busy">Выйти</button><small>СовДело · 0.1</small></div></aside>
 <main class="workspace"><header><div><h1>{{heading}}</h1><p class="muted">{{dateText}}</p></div><div class="actions"><button aria-label="Переключить тему" @click="light=!light">◐</button><button class="primary" @click="showAdd=true;newDate=view==='today'?today():'';newProject=view==='project'?project:null">＋ Задача</button><span class="avatar">{{user.name.slice(0,1)}}</span><button class="mobile-logout" @click="logout">Выйти</button></div></header><p class="stage">ЛОКАЛЬНАЯ ВЕРСИЯ 0.1 <span>· Сохранение в PostgreSQL</span></p><div v-if="error" class="error" role="alert">{{error}} <button class="link" @click="error=''">Закрыть</button></div><div class="toolbar"><input v-model="query" placeholder="Поиск задач…" aria-label="Поиск задач"><button @click="board=!board">{{board?'Список':'Доска'}}</button></div>
 <div :class="['body',{editing:!!draft}]"><section class="task-area"><template v-if="!board"><h2>Задачи <span class="muted">· {{visible.length}}</span></h2><article v-for="t in visible" :key="t.id" :class="['task',{done:t.status==='done',selected:draft?.id===t.id}]" @click="select(t)" @keydown.enter.self="select(t)" tabindex="0" role="button" :aria-label="t.title"><button class="check" :disabled="busy" @click.stop="toggle(t)" :aria-label="t.status==='done'?'Вернуть задачу':'Завершить задачу'">{{t.status==='done'?'✓':''}}</button><div><strong>{{t.title}}</strong><div class="meta"><span v-if="t.project_id" class="tag">{{pname(t.project_id)}}</span><span v-if="t.due_date">{{t.due_date===today()?'Сегодня':t.due_date}}</span><span v-if="t.checklist?.length">☑ {{t.checklist.filter(x=>x.done).length}}/{{t.checklist.length}}</span></div></div><span v-if="t.priority==='high'" class="flag">⚑</span></article></template>
 <div v-else class="board"><section v-for="c in columns" :key="c.id" class="column"><h2>{{c.name}} · {{visible.filter(t=>t.status===c.id).length}}</h2><button v-for="t in visible.filter(t=>t.status===c.id)" :key="t.id" class="task wide" @click="select(t)"><strong>{{t.title}}</strong></button></section></div><div v-if="!visible.length" class="empty"><div>◇</div><h2>Здесь пока нет задач</h2><p>Добавьте задачу — и первое дело уже будет в плане.</p></div></section>
 <aside v-if="draft" class="detail"><div class="detail-head"><h2>Детали задачи</h2><button aria-label="Закрыть детали" @click="draft=null">×</button></div><form @submit.prevent="saveTask"><label>Название<input v-model="draft.title" required maxlength="240"></label><label>Проект<select v-model="draft.project_id"><option :value="null">Без проекта</option><option v-for="p in projects" :key="p.id" :value="p.id">{{p.name}}</option></select></label><div class="two"><label>Статус<select v-model="draft.status"><option v-for="c in columns" :value="c.id" :key="c.id">{{c.name}}</option></select></label><label>Приоритет<select v-model="draft.priority"><option value="normal">Обычный</option><option value="high">Высокий</option></select></label></div><label>Срок<input v-model="draft.due_date" type="date"></label><label>Описание<textarea v-model="draft.description" rows="4" maxlength="20000"></textarea></label><label>Чек-лист</label><div v-for="(s,i) in draft.checklist" :key="i" class="sub"><input type="checkbox" v-model="s.done"><span>{{s.text}}</span><button type="button" @click="draft.checklist!.splice(i,1)" aria-label="Удалить пункт">×</button></div><div class="sub-add"><input v-model="subtext" placeholder="Новый пункт…" maxlength="500" @keydown.enter.prevent="addSub"><button type="button" @click="addSub">＋</button></div><button class="primary wide" :disabled="busy">{{busy?'Сохранение…':'Сохранить изменения'}}</button><button type="button" class="link danger wide" @click="remove" :disabled="busy">Удалить задачу</button></form></aside></div>
 </main>
 <nav class="mobile-nav"><button @click="navigate('today')">▣<br>Сегодня</button><button @click="navigate('inbox')">▱<br>Входящие</button><button @click="navigate('all')">☷<br>Все задачи</button><button @click="showProjects=true">◇<br>Проекты</button></nav>
 <div v-if="showAdd" class="overlay" @click.self="showAdd=false"><form class="modal" @submit.prevent="addTask"><h2>Новая задача</h2><label>Что нужно сделать?<input v-model="newTitle" required maxlength="240" autofocus></label><label>Проект<select v-model="newProject"><option :value="null">Без проекта</option><option v-for="p in projects" :key="p.id" :value="p.id">{{p.name}}</option></select></label><label>Срок<input type="date" v-model="newDate"></label><div class="actions"><button type="button" @click="showAdd=false">Отмена</button><button class="primary" :disabled="busy">Добавить</button></div><p v-if="error" class="error">{{error}}</p></form></div>
 <div v-if="showProjects" class="overlay" @click.self="showProjects=false"><div class="modal"><div class="detail-head"><h2>Проекты</h2><button @click="showProjects=false">×</button></div><button v-for="p in projects" :key="p.id" class="wide" style="margin-bottom:10px" @click="navigate('project',p.id)">{{p.name}}</button><form @submit.prevent="createProject" class="sub-add"><input v-model="projectName" required maxlength="120" placeholder="Новый проект…"><button class="primary" :disabled="busy">＋</button></form></div></div>
 </template>
</div>
</template>
